/**
 * API types and the view models the UI renders.
 *
 * Wire types come from `schema.d.ts`, generated by openapi-typescript from `openapi.json`
 * (which the backend exports: `uv run python scripts/export_openapi.py`, then
 * `npm run gen:api`). Never edit wire shapes by hand: change the backend and regenerate.
 *
 * View models (below the wire aliases) are what components consume. `adapters.ts` builds
 * them from wire responses, so a backend field rename fails typecheck in one place.
 * Money stays a decimal string everywhere; dates are ISO strings.
 */
import type { components } from "./schema";

type S = components["schemas"];

// ---- Wire types (generated) ------------------------------------------------------------

/** Wire shapes, by schema name. Use as Wire["InvoiceDetail"]. */
export interface Wire {
  Readiness: S["Readiness"];
  Sample: S["Sample"];
  RunAccepted: S["RunAccepted"];
  RunRequest: { sample: string; mode: ExecutionMode; evaluation_date?: string | null };
  RunView: S["RunView"];
  AuditEvent: S["AuditEventView"];
  Overview: S["Overview"];
  InvoiceList: S["InvoiceList"];
  InvoiceSummary: S["InvoiceSummary"];
  InvoiceDetail: S["InvoiceDetail"];
  RunSummary: S["RunSummary"];
  VersionView: S["VersionView"];
  CorrectionView: S["CorrectionView"];
  HumanReviewView: S["HumanReviewView"];
  StockLine: S["StockLine"];
  SourceContent: S["SourceContent"];
  ErrorBody: S["ErrorBody"];
}

export type ExecutionMode = S["ExecutionMode"];
export type RunStatus = S["RunStatus"];
export type InvoiceStatus = S["InvoiceStatus"];
export type Severity = S["Severity"];
export type Recommendation = S["Recommendation"];
export type GateOutcome = S["GateOutcome"];
export type SourceFormat = S["SourceFormat"];
/** Closed set from codes.FindingCode; findingCopy.ts has a generic fallback per severity. */
export type FindingCode = S["FindingCode"];

export type EvidenceRef = S["EvidenceRef"];
export type NormalizationEvent = Omit<S["NormalizationEvent"], "evidence"> & { evidence: EvidenceRef[] };
export type ValidationFinding = Omit<S["ValidationFinding"], "evidence" | "code"> & {
  code: FindingCode;
  evidence: EvidenceRef[];
};
export type ApprovalDecision = Omit<S["ApprovalDecision"], "reasons"> & { reasons: string[] };
export type MockReceipt = S["MockReceipt"];
export type LineItem = Omit<S["LineItem"], "evidence"> & { evidence: EvidenceRef[] };
export type StatedTotals = S["StatedTotals"];
export type ComputedTotals = S["ComputedTotals"];
export type ProcessingResult = Omit<S["ProcessingResult"], "errors" | "findings"> & {
  errors: RunErrorCode[];
  findings: ValidationFinding[];
  /**
   * Phase 3 (P3-08) adds these to ProcessingResult; they are absent from today's schema.
   * TODO(P3-08): drop these lines once openapi.json carries them.
   */
  recoverable?: boolean;
  next_actions?: string[];
};
export type ApiErrorBody = Wire["ErrorBody"];

/** Every outcome the status component can show (invoice outcomes plus run-only states). */
export type Outcome =
  | "paid_mock"
  | "rejected"
  | "needs_review"
  | "awaiting_human_approval"
  | "failed"
  | "duplicate"
  | "processing";

/** Error codes in run.error_code / ProcessingResult.errors (intake, parser, model, service). */
export type RunErrorCode =
  | "file_too_large"
  | "unsupported_format"
  | "format_mismatch"
  | "empty_file"
  | "unreadable"
  | "pdf_needs_ocr"
  | "pdf_corrupt"
  | "pdf_encrypted"
  | "too_many_pages"
  | "json_invalid"
  | "xml_invalid"
  | "txt_decode_error"
  | "unsupported_csv_layout"
  | "model_auth_error"
  | "model_rate_limited"
  | "model_timeout"
  | "model_unavailable"
  | "model_output_invalid"
  | "model_refused"
  | "model_budget_exhausted"
  | "model_tool_loop_exceeded"
  | "unexpected_error"
  | "incomplete_graph"
  | "interrupted"
  | (string & {});

/** Decimal string such as "5000.00". Never parsed for display arithmetic. */
export type DecimalStr = string;

// ---- View models (built by adapters.ts) ------------------------------------------------

export interface Readiness {
  offline_available: boolean;
  live_available: boolean;
  /** Why live is unavailable (e.g. "XAI_API_KEY is not set"); never a secret value. */
  live_unavailable_reason: string | null;
  live_settings_present: boolean;
  inventory_seeded: boolean;
  db_path: string;
  schema_version: number;
}

export interface Sample {
  /** Bare basename in data/invoices/, e.g. "invoice_1001.txt". */
  name: string;
  /** Describes the input, never the outcome: "Clean invoice", "Stock mismatch", ... */
  label: string;
  invoice_number: string | null;
  format: string;
  size_bytes: number;
}

/** One persisted audit event, with an operator-facing message derived from it. */
export interface StageEvent {
  sequence: number;
  stage: string;
  event: string;
  message: string | null;
  at: string;
  payload: Record<string, unknown>;
}

export interface RunProgress {
  run_id: string;
  status: RunStatus;
  mode: ExecutionMode;
  current_stage: string | null;
  terminal: boolean;
  invoice_id: string | null;
  source: { source_id: string; original_name: string; format: SourceFormat };
  error_code: RunErrorCode | null;
  error_message: string | null;
  prior_run_id: string | null;
  retry_of: string | null;
  events: StageEvent[];
  result: ProcessingResult | null;
}

export interface RunCreated {
  run_id: string;
  status: RunStatus;
  mode: ExecutionMode;
  idempotent_replay: boolean;
}

export interface InvoiceSummary {
  invoice_id: string;
  invoice_number: string | null;
  vendor: string | null;
  total: string | null;
  currency: string | null;
  status: InvoiceStatus;
  /** Mode of the latest run; historical runs keep their own mode. Null before any run. */
  mode: ExecutionMode | null;
  due_date: string | null;
  latest_run_id: string | null;
  updated_at: string;
}

export interface OverviewCounts {
  unique_invoices: number;
  documents: number;
  runs: number;
  duplicates: number;
  paid_mock: number;
  needs_review: number;
  awaiting_human_approval: number;
  rejected: number;
  failed: number;
  processing: number;
}

export interface Overview {
  counts: OverviewCounts;
  /** Keyed by ISO currency code; never combined across currencies. */
  mock_paid_totals: Record<string, string>;
  recent_invoices: InvoiceSummary[];
}

export interface InvoiceListQuery {
  status?: InvoiceStatus | "";
  mode?: ExecutionMode | "";
  q?: string;
  page?: number;
}

export interface InvoiceList {
  items: InvoiceSummary[];
  page: number;
  page_size: number;
  total: number;
}

export interface DetailLineItem {
  item: string | null;
  /** Quantity on this line. */
  requested: string | null;
  /** null when the item is unknown to inventory. */
  available: number | null;
  unit_price: string | null;
  line_total: string | null;
  /** Aggregated requested quantity of this item minus available, when positive. */
  shortfall: string | null;
  evidence: EvidenceRef[];
}

export interface SourceSummary {
  source_id: string;
  original_name: string;
  format: SourceFormat;
  size_bytes: number;
  page_count: number | null;
}

export interface InvoiceVersion {
  version: number;
  source_id: string;
  original_name: string | null;
  revision: string | null;
  total: string | null;
  currency: string | null;
  created_at: string;
  /** Receipt paid against this version, if any. */
  receipt: MockReceipt | null;
  lines: LineItem[];
}

export interface Correction {
  version: number;
  field: string;
  old_value: string | null;
  new_value: string | null;
  reason: string;
  reviewer: string;
  evidence_location: string;
  created_at: string;
}

export interface HumanReviewRecord {
  version: number;
  action: string;
  reviewer: string;
  reason: string;
  policy_version: string;
  created_at: string;
}

export interface RunSummary {
  run_id: string;
  status: RunStatus;
  mode: ExecutionMode;
  source_id: string;
  original_name: string | null;
  started_at: string;
  finished_at: string | null;
  prior_run_id: string | null;
  retry_of: string | null;
  evaluation_date: string | null;
  error_code: RunErrorCode | null;
  error_message: string | null;
  provider: string | null;
  model: string | null;
  events: StageEvent[];
}

/** Derived from the backend's allowed_actions list (populated by P5-04). */
export interface AllowedActions {
  add_corrected_invoice: boolean;
  correct_extraction: boolean;
  approve_payment: boolean;
  decline_payment: boolean;
  retry: boolean;
}

export interface InvoiceDetail {
  invoice_id: string;
  invoice_number: string | null;
  vendor: string | null;
  status: InvoiceStatus;
  total: string | null;
  currency: string | null;
  due_date: string | null;
  /** Evaluation date of the latest run; drives the Overdue warning. */
  evaluation_date: string | null;
  /** Mode of the latest run (offline when the invoice has no run, which cannot happen today). */
  mode: ExecutionMode;
  current_version: number;
  source: SourceSummary | null;
  stated: StatedTotals;
  computed: ComputedTotals | null;
  normalization_events: NormalizationEvent[];
  findings: ValidationFinding[];
  line_items: DetailLineItem[];
  decision: ApprovalDecision | null;
  receipt: MockReceipt | null;
  latest_result: ProcessingResult | null;
  versions: InvoiceVersion[];
  corrections: Correction[];
  human_reviews: HumanReviewRecord[];
  /** Newest first. */
  runs: RunSummary[];
  allowed_actions: AllowedActions;
}

export interface SourceLine {
  /** Evidence location this line answers to: "line:9", "row:3" (CSV) or "page:1,line:4" (PDF). */
  location: string;
  text: string;
}

export interface SourceContent {
  source_id: string;
  original_name: string;
  format: SourceFormat;
  lines: SourceLine[];
  /** For PDF: URL of the original file for page preview, served by the API. */
  original_url: string | null;
  preview_limitation: string | null;
}
